-- Content pack 8: NEW RULES. 8 rules, 200 examples, 320 exercises.
-- GENERATED by scripts/build-new-rules-pack.mjs from the five files in database/rules-import/ (double_consonants,
-- english_spelling, silent_letters, verb_endings, vowels_and_letter_patterns). Do not edit by hand; edit the JSON
-- and run the script again.
--
-- What it does: adds 8 new built-in rules (double the last consonant / don't double, silent k-w and b-g-h-t,
-- -ed after y, -ing after ie, ch/tch and j/dge, ou/ow/au/aw), each with examples and exercises. Ids are fixed, so the
-- offline copy in the app (src/data/builtInRules.json) matches the database rows exactly.
-- Safe to run more than once: rules are unique on slug, examples and exercises are guarded against duplicates.
-- Run it in the Supabase SQL Editor (project "SpellSprint"). Needs rules-schema.sql to be applied already.
--
-- HOW TO UNDO (removes the rules; their examples and exercises go with them, learner progress on them too):
--   delete from public.rules where slug in ('double-final-consonant-before-suffix', 'no-doubling-unstressed-ending', 'ch-tch-and-j-dge', 'silent-k-and-w', 'silent-b-g-h-t', 'ed-after-y', 'ing-after-ie', 'ou-ow-au-aw-patterns');

begin;

insert into public.rules (id, slug, title, category, rule_type, short_explanation, tts_text, mnemonic, source, visibility, is_active)
values
  ('a986f83f-aab7-54c7-bb18-52ac61f564ef', 'double-final-consonant-before-suffix', 'Double the last consonant: stop → stopped', 'double_consonants', 'language_rule', 'If a word ends in one vowel + one consonant and the last syllable is stressed, double the consonant before -ed, -ing, -er or -est. For example: stop → stopped, begin → beginning.', 'Short stressed vowel plus one consonant: double the consonant before a suffix.', 'One vowel, one consonant, stressed end: double it, friend.', 'built-in', 'public', true),
  ('b1f167ca-3a71-550f-bbfd-76aa7ed19af0', 'no-doubling-unstressed-ending', 'Don''t double: visit → visited, open → opened', 'double_consonants', 'language_rule', 'Do not double the final consonant if the last syllable is not stressed, or if the word ends in two consonants or two vowels. For example: visit → visited, open → opened, wait → waiting.', 'If the last syllable is not stressed, do not double the consonant.', 'Weak ending, no doubling.', 'built-in', 'public', true),
  ('9deba5cf-ddea-5758-a837-0b9c64195fe0', 'ch-tch-and-j-dge', 'ch / tch and j / dge after vowels', 'english_spelling', 'language_rule', 'After a short vowel, use -tch for the /ch/ sound (watch, catch) and -dge for the /j/ sound (bridge, badge). After a long vowel or a consonant, use -ch and -ge: beach, teach, age, large.', 'After a short vowel use tch and dge. Otherwise use ch and ge.', 'Short vowel, strong ending: tch and dge.', 'built-in', 'public', true),
  ('d58743c9-b4f8-5bc5-9c9e-35576d8f817e', 'silent-k-and-w', 'Silent k and w: knife, write, wrong', 'silent_letters', 'language_rule', 'At the start of a word, k before n (knife, know) and w before r (write, wrong) are not pronounced, but you must still write them. A silent w also appears in answer and sword.', 'Write the silent k in know and the silent w in write.', 'Kn and wr: the first letter is silent, but still there.', 'built-in', 'public', true),
  ('ee974e76-1bb2-5358-a736-9141bf6d9d92', 'silent-b-g-h-t', 'Silent b, g, h, t: doubt, sign, hour', 'silent_letters', 'language_rule', 'Some words contain letters you do not pronounce: b in doubt and climb, g in sign and foreign, h in hour and honest, t in listen and castle. Learn these words as whole shapes.', 'Some words keep a silent b, g, h or t, so learn them by sight.', 'Climb the castle, listen to the honest sign.', 'built-in', 'public', true),
  ('7a8d81e6-9838-5c30-a732-c5373787c207', 'ed-after-y', 'Past tense after y: study → studied, play → played', 'verb_endings', 'language_rule', 'If a verb ends in consonant + y, change y to i and add -ed: study → studied. If it ends in vowel + y, just add -ed: play → played.', 'After a consonant, change y to i before ed. After a vowel, keep y.', 'Consonant plus y: say bye to y. Vowel plus y: keep it.', 'built-in', 'public', true),
  ('2d93fade-1889-534a-a1bf-d73fe3f2d710', 'ing-after-ie', '-ing after ie: die → dying, lie → lying', 'verb_endings', 'language_rule', 'If a verb ends in -ie, change ie to y before -ing: die → dying, tie → tying. Never write -ieing.', 'For verbs ending in ie, change ie to y and add ing.', 'I-E turns into Y before ING.', 'built-in', 'public', true),
  ('c58339f3-3bc2-58ea-9651-e5b28aaf2967', 'ou-ow-au-aw-patterns', 'ou / ow / au / aw letter patterns', 'vowels_and_letter_patterns', 'language_rule', 'The letters ou and ow often make the sound in house and how, while au and aw often make the sound in course and saw. Some common words are exceptions, such as soup, should, and daughter.', 'Learn common ou, ow, au and aw words as whole patterns.', 'House and how; course and saw.', 'built-in', 'public', true)
on conflict (slug) do nothing;

